<script setup>
import {computed} from 'vue'
import WorkspaceIcon from './WorkspaceIcon.vue'
import ChangeMethodIllustration from './ChangeMethodIllustration.vue'
import {savedCheckAssessment} from '../change-checks.js'
import {comparisonSummary} from '../comparison-summary.js'
import LogConsultation from './LogConsultation.vue'
const props=defineProps({comparison:Object,baseline:Object,retest:Object,change:Object,trial:Object,conclusions:Array,busy:Boolean})
const emit=defineEmits(['case','career','continue','overview'])
const summary=computed(()=>comparisonSummary(props.comparison,props.baseline,props.retest,props.change))
const checks=computed(()=>savedCheckAssessment(props.change,props.comparison,summary.value))
const show=value=>value==null?'旧记录未提供':value
</script>
<template>
 <section class="comparison-decision panel" aria-label="前后变化概览">
  <div class="comparison-hero"><div><span class="comparison-kicker">{{summary.label}} · 一次对照</span><h2>看看哪些题变了</h2><p>点题号，查看前后回答。</p></div><ChangeMethodIllustration type="COMPARISON" /></div>
  <div class="comparison-counts"><article v-for="[id,label,icon] in [['improved','改善','arrow'],['regressed','退化','arrow'],['unchanged','未变','minus'],['incomplete','未完成','clock'],['notComparable','不可比较','help']]" :key="id" :class="id"><span class="count-symbol"><WorkspaceIcon :name="icon" :size="22" /></span><strong>{{summary.counts[id]}}</strong><span>{{label}}</span></article></div>
  <p v-if="!comparison.comparable" class="note warning">控制条件不一致，不能按单变量比较。{{comparison.comparability_reasons?.join(' · ')}}</p>
  <p v-else-if="!comparison.trust_summary?.overall_improvement_allowed" class="note warning">比较范围受限，暂不能判断整体改善。<button type="button" class="text-button" @click="emit('overview')">查看范围与依据 →</button></p>
  <div class="comparison-next"><button type="button" class="text-button" @click="emit('career')">整理项目 →</button><button type="button" class="text-button" @click="emit('continue')">继续调整 →</button></div>
  <LogConsultation kind="comparison" :comparison="comparison" :baseline-view="baseline" :retest-view="retest" :change="change" :trial="trial" :context="{事实摘要:summary.text,预测与风险:change?.reason||'旧记录未提供',已保存决定:conclusions||[]}" />
  <details class="comparison-more"><summary>查看本轮依据与用量</summary>
  <details><summary>检索结果与回答判定分别看</summary><p>检索：改善 {{summary.retrieval.improved}}，退化 {{summary.retrieval.regressed}}，未变 {{summary.retrieval.unchanged}}，不可比 {{summary.retrieval.notComparable}}。文本包含、独立评分和业务正确性不能互相替代。</p></details>
  <div class="comparison-costs"><div><span>实际请求</span><strong>{{show(summary.beforeCost.requests)}} → {{show(summary.afterCost.requests)}}</strong></div><div><span>已知词元</span><strong>{{show(summary.beforeCost.tokens)}} → {{show(summary.afterCost.tokens)}}</strong></div><div><span>整轮耗时</span><strong>{{summary.beforeCost.elapsedMs==null?'未记录':(summary.beforeCost.elapsedMs/1000).toFixed(1)+'s'}} → {{summary.afterCost.elapsedMs==null?'未记录':(summary.afterCost.elapsedMs/1000).toFixed(1)+'s'}}</strong></div><div><span>实际上下文字符</span><strong>{{show(summary.beforeCost.contextChars)}} → {{show(summary.afterCost.contextChars)}}</strong></div></div><p class="cost-unknown">费用未知；未知用量请求 {{show(summary.beforeCost.unknownUsage)}} → {{show(summary.afterCost.unknownUsage)}} 次。</p>
  <details><summary>退化与目标题优先 · 资料差异</summary><article v-for="p in summary.rows" :key="p.case_id" class="pair-diff"><button type="button" class="text-button" @click="emit('case',p.case_id)">{{p.query||p.case_id}} →</button><p>{{({improved:'改善',regressed:'退化',unchanged:'未变',incomplete:'未完成',notComparable:'不可比较'})[p.category]}}</p><p v-if="p.facts">原文匹配新增 {{p.facts.added.length}} 个要点，丢失 {{p.facts.lost.length}} 个要点；不等于语义正确。</p><p v-else>政策适用性尚未核对，不能按文本匹配宣称要点已覆盖。</p><details><summary>实际上下文：新增 {{p.addedContext.length}} 段 / 丢失 {{p.lostContext.length}} 段</summary><article v-for="(c,i) in p.addedContext" :key="'a'+i" class="added"><strong>新增 · {{c.document_id}} · {{c.chunk_id}}</strong><p>{{c.text}}</p></article><article v-for="(c,i) in p.lostContext" :key="'l'+i" class="lost"><strong>丢失 · {{c.document_id}} · {{c.chunk_id}}</strong><p>{{c.text}}</p></article></details></article></details>
  <details><summary>预测和风险是否得到支持？</summary><article v-for="c in checks" :key="c.label"><h4>{{c.label}} · {{c.status}}</h4><p>{{c.text}}</p><p>{{c.evidence}}</p></article><details><summary>修改前的完整方案记录</summary><p>{{change?.reason||'旧记录未提供'}}</p></details></details>
  </details>
 </section>
</template>
