solid var(--color-success);margin:12px 0;background:var(--color-canvas)}.pair-diff .lost{border-color:var(--color-danger)}.pair-diff p{white-space:pre-wrap}
@media(max-width:1000px){.comparison-counts article{grid-template-columns:1fr;justify-items:center;gap:6px;padding:14px 8px;text-align:center}.count-symbol{grid-row:auto}.comparison-hero>svg{width:200px}}
@media(max-width:650px){.comparison-hero{gap:8px}.comparison-hero h2{font-size:22px}.comparison-hero>svg{width:135px}.comparison-hero p{font-size:14px}.comparison-counts{gap:8px;grid-template-columns:repeat(3,minmax(0,1fr))}.comparison-counts article{grid-template-columns:32px 1fr;text-align:left;justify-items:start;padding:12px 10px;gap:4px 7px}.count-symbol{grid-row:1/3;width:30px;height:30px}.comparison-counts strong{font-size:24px}.comparison-counts article>span:last-child{font-size:12px}.comparison-costs{grid-template-columns:1fr 1fr}}
@media(max-width:430px){.comparison-hero>svg{width:100px}.comparison-counts article{grid-template-columns:1fr;justify-items:center;text-align:center}.count-symbol{grid-row:auto}.comparison-next{gap:10px}.comparison-next button{font-size:13px}}
